import os
import json
from flask import Flask, request, jsonify
from openai import OpenAI
from exa_py import Exa

app = Flask(__name__, static_folder=".", static_url_path="")

exa_api_key = os.environ.get("EXA_API_KEY")
requesty_api_key = os.environ.get("REQUESTY_API_KEY")

if not exa_api_key:
    raise RuntimeError("EXA_API_KEY environment variable is required.")

if not requesty_api_key:
    raise RuntimeError("REQUESTY_API_KEY environment variable is required.")

exa = Exa(exa_api_key)

client = OpenAI(
    api_key=requesty_api_key,
    base_url="https://router.requesty.ai/v1",
)

MODEL_NAME = "zai/glm-5.2"
MAX_SEARCH_QUERIES = 4
MAX_SEARCH_RESULTS = 10
VALID_SEARCH_TYPES = {
    "instant",
    "fast",
    "auto",
    "deep-lite",
    "deep",
    "deep-reasoning",
}

DECISION_SYSTEM_PROMPT = """You are a decision engine. Given the user's conversation, you must decide whether a web search is needed.

You MUST output ONLY a valid JSON object, nothing else, no markdown, no explanation.

If no search is needed:
{"search": false}

If search is needed, output one or more search queries (maximum 4):
{
  "search": true,
  "queries": [
    {
      "query": "the search query string",
      "search_type": "instant",
      "summary_query": "focused summary prompt based on what the user wants to know",
      "include_domains": [],
      "exclude_domains": []
    }
  ]
}

Search type rules:
- instant: simple facts and quick lookups
- fast: recent news and current prices
- auto: general queries
- deep-lite: detailed research topics
- deep: complex multi-faceted research
- deep-reasoning: very hard research questions

Domain rules:
- If the user is searching for apps, always include_domains: ["apps.apple.com", "play.google.com"]
- If the query is about programming or code, always exclude_domains: ["github.com"]
- Otherwise leave both arrays empty.

Do NOT search if:
- The user is doing casual conversation
- The user is asking to translate, rewrite, or summarize text they already provided
- The answer is a stable, timeless fact that cannot have changed
- The user is asking for life advice or opinions

You MUST search if:
- The information could have changed recently, including news, prices, laws, sports, software versions, or people in roles
- The user explicitly asks to search or look something up
- The topic is niche or emerging and you might be wrong
- High-stakes accuracy is needed for medical, legal, or financial information
- The user says "are you sure" or asks you to verify something"""

ANSWER_SYSTEM_PROMPT = """You are a helpful AI assistant. Answer the user's question clearly and thoroughly.
If web search results are provided, use them as your primary source of truth.
When referencing search results, cite the source URL and title naturally in your response.
Always include the publication date if available."""


def normalize_search_type(search_type):
    if isinstance(search_type, str) and search_type in VALID_SEARCH_TYPES:
        return search_type
    return "auto"


def normalize_domains(domains):
    if not isinstance(domains, list):
        return []

    normalized_domains = []

    for domain in domains:
        if isinstance(domain, str):
            cleaned_domain = domain.strip()
            if cleaned_domain:
                normalized_domains.append(cleaned_domain)

    return normalized_domains


def normalize_query_item(query_item):
    if not isinstance(query_item, dict):
        return None

    query = query_item.get("query")
    if not isinstance(query, str) or not query.strip():
        return None

    summary_query = query_item.get("summary_query")
    if not isinstance(summary_query, str) or not summary_query.strip():
        summary_query = query.strip()

    return {
        "query": query.strip(),
        "search_type": normalize_search_type(query_item.get("search_type")),
        "summary_query": summary_query.strip(),
        "include_domains": normalize_domains(query_item.get("include_domains")),
        "exclude_domains": normalize_domains(query_item.get("exclude_domains")),
    }


def normalize_decision(decision):
    if not isinstance(decision, dict):
        return {"search": False, "queries": []}

    if decision.get("search") is not True:
        return {"search": False, "queries": []}

    raw_queries = decision.get("queries")
    if not isinstance(raw_queries, list):
        return {"search": False, "queries": []}

    normalized_queries = []

    for raw_query in raw_queries[:MAX_SEARCH_QUERIES]:
        normalized_query = normalize_query_item(raw_query)
        if normalized_query is not None:
            normalized_queries.append(normalized_query)

    if not normalized_queries:
        return {"search": False, "queries": []}

    return {
        "search": True,
        "queries": normalized_queries,
    }


def serialize_search_result(result):
    return {
        "id": getattr(result, "id", None),
        "url": getattr(result, "url", None),
        "title": getattr(result, "title", None),
        "published_date": getattr(result, "published_date", None),
        "author": getattr(result, "author", None),
        "score": getattr(result, "score", None),
        "summary": getattr(result, "summary", None),
    }


def run_exa_search(
    query,
    search_type,
    summary_query,
    include_domains=None,
    exclude_domains=None,
):
    kwargs = {
        "num_results": MAX_SEARCH_RESULTS,
        "type": normalize_search_type(search_type),
        "contents": {
            "summary": {
                "query": summary_query,
            }
        },
    }

    if include_domains:
        kwargs["include_domains"] = include_domains

    if exclude_domains:
        kwargs["exclude_domains"] = exclude_domains

    try:
        result = exa.search(query, **kwargs)
    except Exception:
        if kwargs["type"] == "auto":
            raise

        kwargs["type"] = "auto"
        result = exa.search(query, **kwargs)

    return [serialize_search_result(result_item) for result_item in result.results]


def get_request_messages():
    payload = request.get_json(silent=True)

    if not isinstance(payload, dict):
        return None, "The request body must be a JSON object."

    messages = payload.get("messages")

    if not isinstance(messages, list) or not messages:
        return None, "The request body must include a non-empty messages array."

    normalized_messages = []

    for message in messages:
        if not isinstance(message, dict):
            return None, "Each message must be a JSON object."

        role = message.get("role")
        content = message.get("content")

        if role not in {"system", "user", "assistant"}:
            return None, "Each message role must be system, user, or assistant."

        if not isinstance(content, str) or not content.strip():
            return None, "Each message content value must be a non-empty string."

        normalized_messages.append(
            {
                "role": role,
                "content": content,
            }
        )

    return normalized_messages, None


@app.route("/")
def index():
    return app.send_static_file("index.html")


@app.route("/chat", methods=["POST"])
def chat():
    messages, validation_error = get_request_messages()

    if validation_error:
        return jsonify({"error": validation_error}), 400

    decision_messages = [
        {
            "role": "system",
            "content": DECISION_SYSTEM_PROMPT,
        }
    ] + messages

    try:
        decision_response = client.chat.completions.create(
            model=MODEL_NAME,
            messages=decision_messages,
            temperature=0,
            max_completion_tokens=1024,
            response_format={"type": "json_object"},
        )
    except Exception as error:
        return jsonify(
            {
                "error": "Unable to determine whether web search is required.",
                "details": str(error),
            }
        ), 502

    decision_content = decision_response.choices[0].message.content

    try:
        decision = normalize_decision(json.loads(decision_content or "{}"))
    except json.JSONDecodeError:
        decision = {"search": False, "queries": []}

    search_context = []
    search_errors = []

    if decision["search"]:
        for query_data in decision["queries"]:
            try:
                results = run_exa_search(
                    query=query_data["query"],
                    search_type=query_data["search_type"],
                    summary_query=query_data["summary_query"],
                    include_domains=query_data["include_domains"] or None,
                    exclude_domains=query_data["exclude_domains"] or None,
                )
                search_context.append(
                    {
                        "query": query_data["query"],
                        "search_type": query_data["search_type"],
                        "results": results,
                    }
                )
            except Exception as error:
                search_errors.append(
                    {
                        "query": query_data["query"],
                        "error": str(error),
                    }
                )

    answer_messages = [
        {
            "role": "system",
            "content": ANSWER_SYSTEM_PROMPT,
        }
    ]

    if search_context:
        answer_messages.append(
            {
                "role": "system",
                "content": "Web search results:\n"
                + json.dumps(search_context, ensure_ascii=False),
            }
        )

    answer_messages += messages

    try:
        answer_response = client.chat.completions.create(
            model=MODEL_NAME,
            messages=answer_messages,
            temperature=0,
            max_completion_tokens=131072,
        )
    except Exception as error:
        return jsonify(
            {
                "error": "Unable to generate an answer.",
                "details": str(error),
                "searched": bool(search_context),
                "search_errors": search_errors,
            }
        ), 502

    reply = answer_response.choices[0].message.content

    if not isinstance(reply, str) or not reply.strip():
        return jsonify(
            {
                "error": "The model returned an empty answer.",
                "searched": bool(search_context),
                "search_errors": search_errors,
            }
        ), 502

    updated_messages = messages + [
        {
            "role": "assistant",
            "content": reply,
        }
    ]

    return jsonify(
        {
            "reply": reply,
            "messages": updated_messages,
            "searched": bool(search_context),
            "search_queries": [
                {
                    "query": query_data["query"],
                    "search_type": query_data["search_type"],
                }
                for query_data in decision["queries"]
            ],
            "search_errors": search_errors,
        }
    )


if __name__ == "__main__":
    app.run(debug=True, port=5000)

